<script setup lang="ts">
import {computed,onScopeDispose,reactive,ref,shallowRef,watch} from 'vue'
import {can,currentProject,projectId,session} from '@/core/session'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {typeDeviceUuid} from './type-devices-api'
import {importSections,importableTypeStatus} from './definition-import-api'
import {productDefinitionImportTransport,prepareProductDefinitionImport,prepareProductDefinitionConfirmation,sameProductDefinitionReceipt,type ProductDefinitionImportTransport,type ProductDefinitionSource,type ProductDefinitionCandidate,type ProductDefinitionPreview,type ProductDefinitionIntent,type ProductDefinitionReceipt} from './product-definition-import-api'
const props=withDefaults(defineProps<{typeId:string;typeStatus:string;active:boolean;disabled?:boolean;transport?:ProductDefinitionImportTransport}>(),{disabled:false,transport:()=>productDefinitionImportTransport})
const emit=defineEmits<{state:[value:{busy:boolean;unknown:boolean;ready:boolean;locked:boolean}];completed:[value:ProductDefinitionReceipt]}>(),roles=['OWNER','ADMIN','OPERATOR','VIEWER'],denied=ref(false)
const member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.typeId)&&can('device:read')&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||'')),readable=computed(()=>member.value&&!denied.value),writable=computed(()=>readable.value&&importableTypeStatus(props.typeStatus)&&currentProject.value?.status==='ACTIVE'&&can('device:update')&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const productId=ref(''),busy=ref(false),pipeline=ref(false),unknown=ref(false),error=ref(''),source=shallowRef<ProductDefinitionSource>(),candidate=shallowRef<ProductDefinitionCandidate>(),preview=shallowRef<ProductDefinitionPreview>(),intent=shallowRef<ProductDefinitionIntent>(),selected=reactive({properties:[] as string[],events:[] as string[],commands:[] as string[]})
const hasSelection=computed(()=>importSections.some(([section])=>selected[section].length)),locked=computed(()=>busy.value||pipeline.value||unknown.value),ready=computed(()=>!!source.value&&hasSelection.value&&!locked.value&&writable.value&&!props.disabled)
let generation=0,alive=true,controller:AbortController|undefined
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,type:props.typeId,actor:session.user?.accountId}}
function current(value:ReturnType<typeof capture>){return alive&&readable.value&&value.generation===generation&&value.epoch===identityEpoch()&&value.project===projectId.value&&value.type===props.typeId&&value.actor===session.user?.accountId}
function clearSelection(){selected.properties=[];selected.events=[];selected.commands=[];candidate.value=undefined;preview.value=undefined}
function reset(clearInput=true){generation++;controller?.abort();busy.value=false;pipeline.value=false;unknown.value=false;source.value=undefined;intent.value=undefined;error.value='';clearSelection();if(clearInput)productId.value=''}
function fail(cause:unknown){if(cause instanceof ApiError&&[401,403].includes(cause.status)&&!cause.outcomeUnknown){reset();denied.value=true}error.value=errorMessage(cause)}
async function lookup(){if(!props.active||!writable.value||props.disabled||locked.value)return;const known=productId.value.trim().toLowerCase();if(!typeDeviceUuid.test(known)){error.value='请输入有效产品 ID';return}const state=capture();busy.value=true;error.value='';source.value=undefined;clearSelection();controller=new AbortController();try{const value=await props.transport.source(state.project,known,controller.signal);if(current(state)&&props.active){if(value.product.productId!==known)throw new Error('读取的产品身份不符，请重新读取');source.value=value}}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged))fail(cause)}finally{if(current(state))busy.value=false}}
function invalidate(){if(!locked.value){candidate.value=undefined;preview.value=undefined;error.value=''}}
function selectionKey(){return importSections.map(([section])=>[...selected[section]].sort().join(',')).join('|')}
async function readPreview(){if(!writable.value||props.disabled||busy.value||unknown.value||!source.value)return;let prepared:ProductDefinitionCandidate;try{prepared=prepareProductDefinitionImport(projectId.value,props.typeId,source.value,selected)}catch(cause){error.value=errorMessage(cause);return}const state=capture();busy.value=true;error.value='';candidate.value=prepared;preview.value=undefined;controller=new AbortController();try{const value=await props.transport.preview(prepared,controller.signal);if(current(state)&&candidate.value===prepared)preview.value=value}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged))fail(cause)}finally{if(current(state))busy.value=false}}
function complete(value:ProductDefinitionReceipt){unknown.value=false;intent.value=undefined;candidate.value=undefined;preview.value=undefined;busy.value=false;pipeline.value=false;emit('completed',value)}
async function confirm(){if(!writable.value||props.disabled||busy.value||unknown.value||!candidate.value||!preview.value||preview.value.issues.length)return;let original:ProductDefinitionIntent;try{original=prepareProductDefinitionConfirmation(candidate.value,preview.value)}catch(cause){error.value=errorMessage(cause);return}intent.value=original;unknown.value=true;busy.value=true;error.value='';const state=capture();controller=new AbortController();let acknowledged=false;try{const value=await props.transport.confirm(original,controller.signal);acknowledged=true;if(!current(state))return;const actual=await props.transport.original(original,controller.signal);if(!current(state))return;if(!sameProductDefinitionReceipt(value,actual))throw new Error('原产品导入回执不一致，请继续按原键核对');complete(actual)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&[401,403].includes(cause.status)){fail(cause);return}error.value=errorMessage(cause);if(!acknowledged&&cause instanceof ApiError&&!cause.outcomeUnknown&&cause.code!==10014&&[400,404,409,413,422,429].includes(cause.status)){unknown.value=false;intent.value=undefined;source.value=undefined;clearSelection();error.value='本次导入被拒绝，请按产品 ID 重新读取后选择。'}}}finally{if(current(state))busy.value=false}}
async function importSelected(){if(!props.active||!ready.value)return;const state=capture(),origin=source.value,keys=selectionKey();pipeline.value=true;try{await readPreview();if(!current(state)||!props.active||!writable.value||props.disabled||source.value!==origin||keys!==selectionKey()||!candidate.value||!preview.value)return;if(preview.value.issues.length){error.value='所选功能存在标识冲突、定义不兼容或来源变化，本次没有导入。';return}await confirm()}finally{if(current(state))pipeline.value=false}}
async function readOriginal(){const original=intent.value;if(!original||!unknown.value||busy.value||!readable.value)return;const state=capture();busy.value=true;error.value='';controller=new AbortController();try{const value=await props.transport.original(original,controller.signal);if(current(state))complete(value)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&cause.status===404)error.value='尚未读到本人原产品导入回执，结果仍未知；不会再次提交。';else fail(cause)}}finally{if(current(state))busy.value=false}}
function finish(){if(!unknown.value||busy.value)return;reset();error.value='已结束核对；原产品导入结果仍未确认，未标记成功。'}
watch(productId,()=>{if(!unknown.value)reset(false)},{flush:'sync'})
watch(()=>props.active,value=>{if(!value&&!unknown.value)reset()},{flush:'sync'})
watch([()=>projectId.value,()=>props.typeId,()=>session.user?.accountId,member,()=>props.transport],()=>{reset();denied.value=false},{flush:'sync'})
watch(()=>props.typeStatus,()=>{if(!unknown.value)reset()},{flush:'sync'})
watch([busy,pipeline,unknown,ready],()=>emit('state',{busy:busy.value||pipeline.value,unknown:unknown.value,ready:ready.value,locked:locked.value}),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(()=>{reset();denied.value=false});onScopeDispose(()=>{alive=false;reset();dispose();emit('state',{busy:false,unknown:false,ready:false,locked:false})})
defineExpose({importSelected})
</script>
<template><section class="product-definition-import"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="unknown"><el-alert title="原产品导入结果尚未确认，只按原键读取，不会再次提交。" type="warning" :closable="false"/><p>产品：{{intent?.candidate.source.product.name}}</p><el-button :loading="busy" :disabled="!readable" @click="readOriginal">读取原产品导入结果</el-button><el-button :disabled="busy" @click="finish">结束本次核对</el-button></template><template v-else><el-form label-position="top" :disabled="locked||disabled||!writable"><el-form-item label="选择已发布的产品"><div class="product-id-row"><el-input v-model="productId" placeholder="请输入产品 ID" aria-label="导入功能产品 ID" maxlength="36"/><el-button :loading="busy" :disabled="!productId.trim()" @click="lookup">读取</el-button></div></el-form-item></el-form><el-empty v-if="!source" description="暂无可用的功能列表" :image-size="64"/><template v-else><p class="product-source">{{source.product.name}} · 已发布第 {{source.product.sequence}} 版</p><section v-for="[section,label] in importSections" :key="section" class="product-selection"><h4>{{label}}（{{source.choices[section].length}} 项）</h4><p v-if="!source.choices[section].length">产品暂无{{label}}。</p><el-checkbox-group v-model="selected[section]" :aria-label="`选择产品${label}`" :disabled="locked||disabled||!writable" @change="invalidate"><el-checkbox v-for="row in source.choices[section]" :key="row.key" :value="row.key">{{row.name}}（{{row.key}}）</el-checkbox></el-checkbox-group></section></template></template></section></template>
<style scoped>.product-id-row{display:flex;gap:12px;width:100%}.product-id-row .el-input{flex:1}.product-source{font-size:14px;color:var(--tl-title)}.product-selection{margin:16px 0}.product-selection h4{font-size:14px;font-weight:500;margin:14px 0 8px}.product-selection p{font-size:13px;color:var(--tl-muted)}.product-selection :deep(.el-checkbox-group){display:flex;flex-wrap:wrap;gap:6px 18px}.product-selection :deep(.el-checkbox){margin-right:0;height:auto;min-height:28px}.el-alert{margin:12px 0}</style>
